code.formula:
@Command([EditDocument];"1");

@If(Category=""; 			@Return(@Do(@Command([EditGotoField];"Category");		@Prompt([Ok];"Missing Value"; "Please select the Category!")));"");
@If(SendTo=""; 			@Return(@Do(@Command([EditGotoField];"SendTo");		@Prompt([Ok];"Missing Value"; "Please select the HOD!")));"");
@If(Name=""; 				@Return(@Do(@Command([EditGotoField];"Name");			@Prompt([Ok];"Missing Value"; "Please state the Name before proceeding!")));"");
@If(Type=""; 				@Return(@Do(@Command([EditGotoField];"Type");			@Prompt([Ok];"Missing Value"; "Please enter the Type before proceeding!")));"");
@If(Designation=""; 		@Return(@Do(@Command([EditGotoField];"Designation");	@Prompt([Ok];"Missing Value"; "Please enter the Designation before proceeding!")));"");

@If(Type="Permanent" & NoWorkers="";			@Return(@Do(@Command([EditGotoField];"NoWorkers");			 @Prompt([Ok];"Missing Value"; "Please state the Number of Workers before proceeding!")));"");
@If(Type="Permanent" & Category!="Reduction" & Workstation=""; 			
																			@Return(@Do(@Command([EditGotoField];"Workstation");			 @Prompt([Ok];"Missing Value"; "Please state the Workstation before proceeding!")));"");
@If(Type="Permanent" & JD="" & Category!="Reduction"; 							
																			@Return(@Do(@Command([EditGotoField];"JD");						 @Prompt([Ok];"Missing Value"; "Please state the Job Description before proceeding!")));"");
@If(Type="Permanent" & CurrentNoWorkers="";	@Return(@Do(@Command([EditGotoField];"CurrentNoWorkers");@Prompt([Ok];"Missing Value"; "Please state the current number of Workers before proceeding!")));"");
@If(Type="Permanent" &  Category!="Reduction" & Period="";					@Return(@Do(@Command([EditGotoField];"Period");					
																			@Prompt([Ok];"Missing Value"; "Please state the required period before proceeding!")));"");
@If(Type="Permanent" & Justification="";			@Return(@Do(@Command([EditGotoField];"Justification");			 @Prompt([Ok];"Missing Value"; "Please state the justification before proceeding!")));"");

@If(Type="Shutdown" & NoWorkers2="";			@Return(@Do(@Command([EditGotoField];"NoWorkers2");			@Prompt([Ok];"Missing Value"; "Please state the Number of Workers before proceeding!")));"");
@If(Type="Shutdown" & Workstation2=""; 			@Return(@Do(@Command([EditGotoField];"Workstation2");		@Prompt([Ok];"Missing Value"; "Please state the Workstation before proceeding!")));"");
@If(Type="Shutdown" & JD2=""; 							@Return(@Do(@Command([EditGotoField];"JD2");						@Prompt([Ok];"Missing Value"; "Please state the Job Description before proceeding!")));"");

FIELD DateIssued := @Now;
FIELD CurrentAction := "Submitted";
FIELD RemDate := @Adjust(@Today;0;0;7;0;0;0);

@Command([ViewRefreshFields]);
@Command([FileSave]);

@MailSend(SendTo;HR;NULL;"Contract Worker Requisition - Submitted for Approval - "+IssueNo;NULL;"Please follow this doclink  ------> ";[IncludeDoclink]);

@Command([ViewRefreshFields]);
@PostedCommand([FileSave]);
@Command([FileCloseWindow])

