code.formula:
@Command([EditDocument];"1");

@If(Name=""; 			@Return(@Do(@Command([EditGotoField];"Name");			@Prompt([Ok];"Missing Value"; "Please state the Name!")));"");
@If(EmpNo=""; 		@Return(@Do(@Command([EditGotoField];"EmpNo");			@Prompt([Ok];"Missing Value"; "Please enter the Employee No.!")));"");
@If(Section=""; 		@Return(@Do(@Command([EditGotoField];"Section");			@Prompt([Ok];"Missing Value"; "Please select the Section!")));"");
@If(Company=""; 	@Return(@Do(@Command([EditGotoField];"Company");		@Prompt([Ok];"Missing Value"; "Please select the Company!")));"");
@If(WPNo=""; 			@Return(@Do(@Command([EditGotoField];"WPNo");			@Prompt([Ok];"Missing Value"; "Please enter the Work Permit No.!")));"");
@If(WPPeriod=""; 	@Return(@Do(@Command([EditGotoField];"WPPeriod");	@Prompt([Ok];"Missing Value"; "Please select the Work Permit Period!")));"");
@If(WPPeriod2=""; 	@Return(@Do(@Command([EditGotoField];"WPPeriod2");	@Prompt([Ok];"Missing Value"; "Please select the Work Permit Period!")));"");
@If(EmpNo=""; 		@Return(@Do(@Command([EditGotoField];"EmpNo");			@Prompt([Ok];"Missing Value"; "Please enter the Employee No.!")));"");
@If(PIC=""; 				@Return(@Do(@Command([EditGotoField];"PIC");				@Prompt([Ok];"Missing Value"; "Please select the PIC!")));"");
@If(Section2=""; 		@Return(@Do(@Command([EditGotoField];"Section2");		@Prompt([Ok];"Missing Value"; "Please select the Previous Section!")));"");
@If(Company2=""; 	@Return(@Do(@Command([EditGotoField];"Company2");	@Prompt([Ok];"Missing Value"; "Please select the Previous Company!")));"");
@If(Status=""; 			@Return(@Do(@Command([EditGotoField];"Status");			@Prompt([Ok];"Missing Value"; "Please select the Status!")));"");

FIELD DateIssued := @Now;
FIELD CA := "Submitted";

@Command([ViewRefreshFields]);
@Command([FileSave]);

@MailSend(HR;HRHOD;NULL;"Current Contract Worker Requisition - Submitted for HR Acknowledgement - "+IssueNo;NULL;"Please follow this doclink  ------> ";[IncludeDoclink]);

